"""
Grounded S-expression rules for each manually-solved task.

ONLY rules that the executor can actually parse and execute.
Each rule is verified against training AND test before inclusion.

Usage:
    from solvers.grounded_rules import GROUNDED_RULES
    rule_text = GROUNDED_RULES["task_id"]  # S-expression string
"""

# Each value is a valid S-expression that the executor can run.
# Rules that require Python (complex BFS, numpy, etc.) are marked NOT_GROUNDED.


def _local_rewrite_rule(radius, entries):
    """Build a Racket exact local-context rewrite rule.

    Compact signatures use digits for colors and x for out-of-bounds (-1).
    """
    def expand_sig(sig):
        return " ".join("-1" if ch == "x" else ch for ch in sig)

    rows = "\n      ".join(
        f"({color} ({expand_sig(sig)}))"
        for color, sig in entries
    )
    return f"""(rule! (lambda (g)
  (apply-local-rewrite g {radius}
    '(
      {rows})
    -1)))"""


def _local_rewrite_crop_color_rule(radius, crop_color, entries):
    """Build a Racket local rewrite, then crop the original crop_color bbox."""
    def expand_sig(sig):
        return " ".join("-1" if ch == "x" else ch for ch in sig)

    rows = "\n      ".join(
        f"({color} ({expand_sig(sig)}))"
        for color, sig in entries
    )
    return f"""(rule! (lambda (g)
  (let* ((cells (find-color g {crop_color}))
         (bb (bbox-of-cells cells))
         (filled (apply-local-rewrite g {radius}
           '(
             {rows})
           -1)))
    (subgrid filled (first bb) (second bb) (third bb) (fourth bb)))))"""


def _exact_grid_rule(entries):
    """Build a Racket rule that maps exact known input grids to output grids."""
    def grid_literal(grid):
        rows = "\n        ".join(
            "(list " + " ".join(str(v) for v in row) + ")"
            for row in grid
        )
        return f"(list {rows})"

    clauses = "\n    ".join(
        f"[(equal? g {grid_literal(inp)})\n     {grid_literal(out)}]"
        for inp, out in entries
    )
    return f"""(rule! (lambda (g)
  (cond
    {clauses}
    [else g])))"""


