def verify_all():
    """Verify all grounded rules against training + test."""
    import sys
    sys.path.insert(0, ".")
    from arc_repl.executor import ArcExecutor
    from arc_repl.builtins import _unwrap
    from src.core.data_loader import load_challenges, load_solutions

    challenges = load_challenges("training")
    solutions = load_solutions("training")

    ok = 0
    for tid, rule_text in GROUNDED_RULES.items():
        task = challenges[tid]
        ex = ArcExecutor(task, auto_scan_on_load=False)

        result = ex.step(rule_text)
        if "ERROR" in result:
            print(f"  FAIL {tid}: executor error: {result[:80]}")
            continue

        all_pass = True
        for i in range(len(task["train"])):
            r = ex.step(f"(test! {i})")
            if "PASS" not in r:
                all_pass = False
                print(f"  FAIL {tid} pair {i}: {r[:60]}")
                break

        if not all_pass:
            continue

        for i in range(len(task["test"])):
            ex.step(f"(apply! {i})")

        correct = all(
            _unwrap(ex._results.get(f"_{i+1}")) == solutions[tid][i]
            for i in range(len(solutions[tid]))
        )

        if correct:
            ok += 1
            print(f"  OK {tid}")
        else:
            print(f"  WRONG {tid}")

    print(f"\n{ok}/{len(GROUNDED_RULES)} grounded rules verified")
    print(f"{len(NOT_GROUNDED)} rules need conversion")


if __name__ == "__main__":
    verify_all()
